import 'package:flutter/material.dart';
import 'dart:math' as math;

class CircleMenuDelegate extends FlowDelegate {
  final Animation<double> menuAnimation;
  final int itemCount;
  final double radius;

  CircleMenuDelegate({
    required this.menuAnimation,
    required this.itemCount,
    this.radius = 100.0,
  }) : super(repaint: menuAnimation);

  @override
  void paintChildren(FlowPaintingContext context) {
    final double angleStep = (2 * math.pi) / itemCount;
    final double animationValue = menuAnimation.value;

    for (int i = 0; i < itemCount; i++) {
      final double angle = i * angleStep;
      final double x = math.cos(angle) * radius * animationValue;
      final double y = math.sin(angle) * radius * animationValue;

      context.paintChild(
        i,
        transform: Matrix4.translationValues(
          x - 25 + context.size.width / 2,
          y - 25 + context.size.height / 2,
          0.0,
        ),
      );
    }
  }

  @override
  Size getSize(BoxConstraints constraints) {
    return Size(radius * 2 + 50, radius * 2 + 50);
  }

  @override
  bool shouldRepaint(CircleMenuDelegate oldDelegate) {
    return menuAnimation != oldDelegate.menuAnimation ||
           itemCount != oldDelegate.itemCount ||
           radius != oldDelegate.radius;
  }
}

